INSERT INTO keypad_command (panel_model_id, slug, keys, label, kind, description, position, payload)
	VALUES ((SELECT id FROM panel_model WHERE slug = 'pc1864'), $q$k1$q$, $q$[*][1]$q$, $q$Bypass zones$q$, $q$command$q$, $q$When disarmed, opens bypass mode: enter a 2-digit zone number to bypass or unbypass it, then [#] to finish. When armed Stay, [*][1] re-activates the Stay/Away zones (switches to Away).$q$, 0, $q${"entries":[{"label":"[zone 01-64]","note":"Toggle bypass on that zone"},{"label":"[99]","note":"Bypass recall: recall the last group of bypassed zones"},{"label":"[00]","note":"Clear all bypasses"},{"label":"[95]","note":"Save the current bypass group"},{"label":"[91]","note":"Recall the saved bypass group"}],"tips":["If [015] option 5 is ON, a user code is required after [*][1].","Hold-up zones cannot be in a bypass group."],"related":["s013"]}$q$::jsonb);
INSERT INTO keypad_command (panel_model_id, slug, keys, label, kind, description, position, payload)
	VALUES ((SELECT id FROM panel_model WHERE slug = 'pc1864'), $q$k2$q$, $q$[*][2]$q$, $q$Trouble display$q$, $q$command$q$, $q$Shows which trouble conditions are present. On an LED keypad the zone lights 1-8 show the trouble type. Press the number to drill into that trouble.$q$, 1, $q${"entries":[{"label":"[1] Service required","note":"Press [1] again for detail: 1 low battery, 2 bell circuit, 3 general system trouble, 4 general system tamper, 5 module supervision, 6 RF jam, 7 PC5204 low battery, 8 PC5204 AC failure"},{"label":"[2] AC failure","note":"No AC power at the panel"},{"label":"[3] Telephone line trouble","note":"TLM. Turn off [015] option 7 if no phone line is connected"},{"label":"[4] Failure to communicate","note":"Panel could not reach the central station"},{"label":"[5] Zone fault","note":"Press [5] to see which zones"},{"label":"[6] Zone tamper","note":"Press [6] to see which zones"},{"label":"[7] Wireless low battery","note":"Press [7] repeatedly: zones, handheld keypads, wireless keys"},{"label":"[8] Loss of clock","note":"Set time with [*][6][master code][1]"}],"related":["s015","k6"]}$q$::jsonb);
INSERT INTO keypad_command (panel_model_id, slug, keys, label, kind, description, position, payload)
	VALUES ((SELECT id FROM panel_model WHERE slug = 'pc1864'), $q$k3$q$, $q$[*][3]$q$, $q$Alarm memory$q$, $q$command$q$, $q$Shows the zones that went into alarm during the last armed period. To clear the Memory light, arm then disarm.$q$, 2, $q${}$q$::jsonb);
INSERT INTO keypad_command (panel_model_id, slug, keys, label, kind, description, position, payload)
	VALUES ((SELECT id FROM panel_model WHERE slug = 'pc1864'), $q$k4$q$, $q$[*][4]$q$, $q$Door chime on/off$q$, $q$command$q$, $q$Toggles door chime. Three quick beeps means chime is now ON; one long 2-second tone means it is now OFF.$q$, 3, $q${"related":["s101"]}$q$::jsonb);
INSERT INTO keypad_command (panel_model_id, slug, keys, label, kind, description, position, payload)
	VALUES ((SELECT id FROM panel_model WHERE slug = 'pc1864'), $q$k5$q$, $q$[*][5][Master code]$q$, $q$User codes$q$, $q$command$q$, $q$Program user access codes. After the master code, enter the 2-digit user number, then the new 4-digit code (6 digits if [701] option 5 is ON). Press [*] instead of a code to delete it.$q$, 4, $q${"entries":[{"label":"[01]-[39], [41]-[95]","note":"General user codes (arm/disarm)"},{"label":"[40]","note":"Master code (all functions). Default 1234"},{"label":"[98] + user number","note":"Partition assignment: press 1-8 to toggle partitions"},{"label":"[99] + user number","note":"User attributes: press 1-8 to toggle"}],"attributes":[{"n":1,"on":"Can enter user code programming (supervisor)"},{"n":2,"on":"Duress code: sends a duress report when used"},{"n":3,"on":"Can manually bypass zones"},{"n":4,"on":"Escort5580 remote access"},{"n":5,"on":"For future use"},{"n":6,"on":"For future use"},{"n":7,"on":"Bell squawk on arm/disarm"},{"n":8,"on":"One-time use code (resets at midnight)"}],"related":["s007","s015"]}$q$::jsonb);
INSERT INTO keypad_command (panel_model_id, slug, keys, label, kind, description, position, payload)
	VALUES ((SELECT id FROM panel_model WHERE slug = 'pc1864'), $q$k6$q$, $q$[*][6][Master code]$q$, $q$User functions$q$, $q$command$q$, $q$After the master code, press the number for the function. On LCD keypads you can also scroll with the arrow keys and press [*].$q$, 5, $q${"entries":[{"label":"[1] Time and date","note":"Enter HH MM MM DD YY in 24-hour time. 6:00 pm on 29 June 2025 = 18 00 06 29 25"},{"label":"[2] Auto-arm/disarm on/off","note":"Three beeps = enabled, long tone = disabled"},{"label":"[3] Auto-arm time","note":"Press day (1=Sunday ... 7=Saturday) then HH MM"},{"label":"[4] System test","note":"Bell, buzzer and lights for 2 seconds, battery test, test report"},{"label":"[5] Enable DLS window","note":"Opens a 1 or 6 hour downloading window ([702] option 7)"},{"label":"[6] User-initiated DLS call","note":"Panel calls the DLS computer"},{"label":"[7]-[8]","note":"For future use"},{"label":"LCD extras","note":"Event buffer, brightness, contrast and buzzer level by scrolling"}],"tips":["If [019] option 7 is ON, every user code can open this menu, not only the master code."],"related":["s019","s401"]}$q$::jsonb);
INSERT INTO keypad_command (panel_model_id, slug, keys, label, kind, description, position, payload)
	VALUES ((SELECT id FROM panel_model WHERE slug = 'pc1864'), $q$k7$q$, $q$[*][7][1-4]$q$, $q$Command outputs$q$, $q$command$q$, $q$Activates PGM outputs set to command output 1-4. [*][7][2] is normally fire/smoke sensor reset.$q$, 6, $q${"entries":[{"label":"[1]","note":"Command output 1 (PGM type 19)"},{"label":"[2]","note":"Command output 2 / sensor reset (PGM type 20 or 03)"},{"label":"[3]","note":"Command output 3 (PGM type 21)"},{"label":"[4]","note":"Command output 4 (PGM type 22)"}],"related":["s009","s501"]}$q$::jsonb);
INSERT INTO keypad_command (panel_model_id, slug, keys, label, kind, description, position, payload)
	VALUES ((SELECT id FROM panel_model WHERE slug = 'pc1864'), $q$k8$q$, $q$[*][8][Installer code]$q$, $q$Installer programming$q$, $q$command$q$, $q$Enter installer programming. The default installer code is 5555. The Armed light ON means the panel is waiting for a 3-digit section number. The Ready light ON means it is waiting for data inside a section.$q$, 7, $q${"tips":["You cannot enter installer programming while armed or in alarm.","Press [#] when the Armed light is on to leave installer programming."],"related":["s006"]}$q$::jsonb);
INSERT INTO keypad_command (panel_model_id, slug, keys, label, kind, description, position, payload)
	VALUES ((SELECT id FROM panel_model WHERE slug = 'pc1864'), $q$k9$q$, $q$[*][9][User code]$q$, $q$No-entry arming$q$, $q$command$q$, $q$Arms in Stay mode with no entry delay: Delay zones act as Instant zones. The Armed light flashes to show it.$q$, 8, $q${}$q$::jsonb);
INSERT INTO keypad_command (panel_model_id, slug, keys, label, kind, description, position, payload)
	VALUES ((SELECT id FROM panel_model WHERE slug = 'pc1864'), $q$k0$q$, $q$[*][0]$q$, $q$Quick arm / quick exit$q$, $q$command$q$, $q$Disarmed: arms without a code ([015] option 4). Armed: Quick Exit lets one Delay zone open once in the next 2 minutes ([015] option 3).$q$, 9, $q${"related":["s015"]}$q$::jsonb);

